// Temporary beta-test tolerance for indoor store GPS. This is a separate,
// action-time proof and never alters the protected delivery geofence.
const STORE_PRESENCE_RETURN_PROOF_RADIUS_METRES = 10;
const STORE_PRESENCE_START_PROOF_DEFAULT_RADIUS_METRES = 25;
const STORE_PRESENCE_START_PROOF_MIN_RADIUS_METRES = 5;
const STORE_PRESENCE_START_PROOF_MAX_RADIUS_METRES = 50;
const STORE_PRESENCE_PROOF_MAX_ACCURACY_METRES = 30;
const STORE_PRESENCE_PROOF_MAX_AGE_MS = 30_000;

function storePresenceStartProofRadius(settings: Settings) {
  const value = settings.storePresenceStartProofRadiusMetres;
  return Number.isFinite(value) &&
    value! >= STORE_PRESENCE_START_PROOF_MIN_RADIUS_METRES &&
    value! <= STORE_PRESENCE_START_PROOF_MAX_RADIUS_METRES
    ? Math.round(value!)
    : STORE_PRESENCE_START_PROOF_DEFAULT_RADIUS_METRES;
}

function storePresenceProofEnabled(activity: ActivityRecord) {
  const proof = activity.storePresenceProof;
  return proof
    ? (proof.changes.at(-1)?.enabled ?? proof.enabledAtStart)
    : false;
}

function storePresenceProofStatus(
  activity: ActivityRecord | null | undefined,
  fix: StoreProofFix | null,
  now = Date.now(),
) {
  const proof = activity?.storePresenceProof;
  if (!proof || !storePresenceProofEnabled(activity!))
    return {
      required: false,
      confirmed: true,
      message: "Store-presence proof is off",
    };
  if (
    !fix ||
    !nativeSampleIsFresh(fix.timestamp, now, STORE_PRESENCE_PROOF_MAX_AGE_MS)
  )
    return {
      required: true,
      confirmed: false,
      message: "Waiting for a fresh store GPS fix",
    };
  const distance = distanceMetres(
    fix.latitude,
    fix.longitude,
    proof.latitude,
    proof.longitude,
  );
  if (fix.accuracy > STORE_PRESENCE_PROOF_MAX_ACCURACY_METRES)
    return {
      required: true,
      confirmed: false,
      distance,
      message: `GPS needs to be ±${STORE_PRESENCE_PROOF_MAX_ACCURACY_METRES}m or better`,
    };
  if (distance > proof.radiusMetres)
    return {
      required: true,
      confirmed: false,
      distance,
      message: `${Math.round(distance)}m from the ${proof.radiusMetres}m store proof zone`,
    };
  return {
    required: true,
    confirmed: true,
    distance,
    message: `Inside ${proof.radiusMetres}m proof zone · GPS ±${Math.round(fix.accuracy)}m`,
  };
}

/** A separate, foreground, action-time check. It never starts or alters delivery GPS/geofence tracking. */
function storePresenceStartProofStatus(
  settings: Settings,
  fix: StoreProofFix | null,
  now = Date.now(),
) {
  if (settings.storePresenceStartProofEnabled !== true)
    return {
      required: false,
      confirmed: true,
      message: "Store-start proof is off",
    };
  const radius = storePresenceStartProofRadius(settings);
  if (
    !fix ||
    !nativeSampleIsFresh(fix.timestamp, now, STORE_PRESENCE_PROOF_MAX_AGE_MS)
  )
    return {
      required: true,
      confirmed: false,
      message: "Verify a fresh store GPS fix",
    };
  const store = getStoreDisplayLocation(settings);
  const distance = distanceMetres(
    fix.latitude,
    fix.longitude,
    store.latitude,
    store.longitude,
  );
  if (fix.accuracy > STORE_PRESENCE_PROOF_MAX_ACCURACY_METRES)
    return {
      required: true,
      confirmed: false,
      distance,
      message: `GPS needs to be ±${STORE_PRESENCE_PROOF_MAX_ACCURACY_METRES}m or better`,
    };
  if (distance > radius)
    return {
      required: true,
      confirmed: false,
      distance,
      message: `${Math.round(distance)}m from the ${radius}m store proof zone`,
    };
  return {
    required: true,
    confirmed: true,
    distance,
    message: `Inside ${radius}m proof zone · GPS ±${Math.round(fix.accuracy)}m`,
  };
}
