/** Bounded, deterministic revision for one permanent source-side retraction. */
function shiftRetractionRevision(shift: Shift) {
  let value = 17;
  for (const character of `${shift.id}|${shift.updatedAt}|retracted`)
    value = (value * 31 + character.charCodeAt(0)) % 1_000_001;
  return value;
}
