function isPwaInstalled() {
  const iosNavigator = navigator as Navigator & { standalone?: boolean };
  return (
    window.matchMedia("(display-mode: standalone)").matches ||
    iosNavigator.standalone === true ||
    localStorage.getItem(INSTALLED_KEY) === "1"
  );
}

/**
 * This is deliberately a same-origin health check, not a Google probe: it
 * costs no Google Routes quota. The worker bypasses its offline cache fallback
 * for this endpoint, so two successes ten seconds apart are a useful stable
 * connection gate before the two real route calls are allowed to start.
 */
async function hasStableInternetProbe() {
  if (navigator.onLine === false || typeof fetch !== "function") return false;
  const controller = new AbortController();
  const timeout = window.setTimeout(
    () => controller.abort(),
    GOOGLE_CONNECTION_PROBE_TIMEOUT_MS,
  );
  try {
    const response = await fetch(`/api/connection?check=${Date.now()}`, {
      method: "HEAD",
      cache: "no-store",
      signal: controller.signal,
      headers: { "Cache-Control": "no-store" },
    });
    return response.status === 204;
  } catch {
    return false;
  } finally {
    window.clearTimeout(timeout);
  }
}


type ExpectedRouteCustomer = NonNullable<
  NonNullable<ActivityRecord["expectedRoute"]>["customer"]
>;
type DeliveryStartProofModalState = {
  status: "checking" | "confirmed" | "failed";
  message: string;
  detail?: string;
};

/** A double is one ordered Google route to both customers, then the ordinary return. */
function expectedRoutePlan(
  activity: ActivityRecord,
  finalCustomer: ExpectedRouteCustomer,
) {
  if (
    !Number.isFinite(finalCustomer.latitude) ||
    !Number.isFinite(finalCustomer.longitude)
  )
    return null;
  if (activity.type !== "double_delivery")
    return {
      intermediates: [] as { latitude: number; longitude: number }[],
      serviceAllowanceSeconds: 120,
    };
  const firstCustomer = manualDeliveredCustomerEvents(activity).find(
    (event) =>
      event.latitude != null &&
      event.longitude != null &&
      Number.isFinite(event.latitude) &&
      Number.isFinite(event.longitude),
  );
  if (
    !firstCustomer ||
    firstCustomer.latitude == null ||
    firstCustomer.longitude == null
  )
    return null;
  return {
    intermediates: [
      { latitude: firstCustomer.latitude, longitude: firstCustomer.longitude },
    ],
    serviceAllowanceSeconds: 240,
  };
}

/**
 * Road ETA starts at the physical store pin and ends at it again, whereas the
 * recorded timer also includes getting out of and back into the store. Use
 * only other completed, non-test runs from the same Monday–Sunday week so a
 * delivery cannot teach its own benchmark.
 */
const weeklyHustleAllowance = createHustleAllowanceCache();

const timeFormat = new Intl.DateTimeFormat("en-GB", {
  hour: "2-digit",
  minute: "2-digit",
  hour12: false,
});
const dayFormat = new Intl.DateTimeFormat("en-GB", {
  weekday: "long",
  day: "numeric",
  month: "long",
});
const shortDayFormat = new Intl.DateTimeFormat("en-GB", {
  weekday: "short",
  day: "numeric",
  month: "short",
});

function toLocalInput(iso: string | null) {
  if (!iso) return "";
  const date = new Date(iso);
  const local = new Date(date.getTime() - date.getTimezoneOffset() * 60_000);
  return local.toISOString().slice(0, 16);
}

function fromLocalInput(value: string) {
  return value ? new Date(value).toISOString() : null;
}

function toDateInput(date: Date) {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
}

function monthKey(date: Date) {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}`;
}
function defaultPayrollSchedule(date: Date): PayrollSchedule {
  const monthStart = new Date(date.getFullYear(), date.getMonth(), 1, 12);
  const cutoff = new Date(date.getFullYear(), date.getMonth(), 23, 12);
  const periodStart = new Date(cutoff);
  periodStart.setDate(periodStart.getDate() - 27);
  const payday = new Date(date.getFullYear(), date.getMonth() + 1, 1, 12);
  return {
    monthKey: monthKey(monthStart),
    periodStartDate: toDateInput(periodStart),
    cutoffDate: toDateInput(cutoff),
    paydayDate: toDateInput(payday),
    isFiveWeekPay: false,
    paidAt: null,
  };
}

function payrollDateLabel(value: string, year = false) {
  return new Date(`${value}T12:00:00`).toLocaleDateString("en-GB", {
    day: "numeric",
    month: "short",
    ...(year ? { year: "numeric" } : {}),
  });
}

function payrollPeriodLabel(schedule: PayrollSchedule, year = false) {
  return `${payrollDateLabel(payrollPeriodStart(schedule), year)} – ${payrollDateLabel(schedule.cutoffDate, year)}`;
}

function csvCell(value: string | number) {
  const string = String(value);
  return /[",\n]/.test(string) ? `"${string.replaceAll('"', '""')}"` : string;
}

async function resizeAddressImage(file: File): Promise<string> {
  const bitmap = await createImageBitmap(file);
  const scale = Math.min(1, 1600 / Math.max(bitmap.width, bitmap.height));
  const canvas = document.createElement("canvas");
  canvas.width = Math.max(1, Math.round(bitmap.width * scale));
  canvas.height = Math.max(1, Math.round(bitmap.height * scale));
  canvas.getContext("2d")?.drawImage(bitmap, 0, 0, canvas.width, canvas.height);
  bitmap.close();
  return canvas.toDataURL("image/jpeg", 0.84);
}

