function ShiftContextModal({
  existing,
  onCancel,
  onSave,
}: {
  existing?: ShiftContext;
  onCancel: () => void;
  onSave: (value: ShiftContext) => void;
}) {
  const now = new Date().toISOString();
  const [manager, setManager] = useState(existing?.managerOnDuty ?? "");
  const [tags, setTags] = useState<ShiftContextTag[]>(existing?.tags ?? []);
  const [note, setNote] = useState(existing?.note ?? "");
  const toggle = (tag: ShiftContextTag) =>
    setTags((current) =>
      current.includes(tag)
        ? current.filter((item) => item !== tag)
        : [...current, tag],
    );
  return (
    <div className="modal-backdrop" role="presentation">
      <div
        className="confirm-modal shift-context-modal"
        role="dialog"
        aria-modal="true"
        aria-labelledby="shift-context-title"
      >
        <p className="eyebrow">SHIFT CONTEXT</p>
        <h2 id="shift-context-title">What affected this shift?</h2>
        <p>
          Optional operational context only. It never changes pay, mileage, GPS
          or delivery timings.
        </p>
        <label>
          Manager on duty
          <input
            value={manager}
            onChange={(event) => setManager(event.target.value)}
            placeholder="Optional"
          />
        </label>
        <div className="context-tag-grid">
          {SHIFT_CONTEXT_OPTIONS.map((item) => (
            <button
              type="button"
              className={tags.includes(item.value) ? "selected" : ""}
              aria-pressed={tags.includes(item.value)}
              key={item.value}
              onClick={() => toggle(item.value)}
            >
              {item.label}
            </button>
          ))}
        </div>
        <label>
          Optional note
          <textarea
            rows={3}
            maxLength={500}
            value={note}
            onChange={(event) => setNote(event.target.value)}
            placeholder="Do not include customer names or addresses"
          />
        </label>
        <div>
          <button onClick={onCancel}>CANCEL</button>
          <button
            className="confirm-primary"
            onClick={() =>
              onSave({
                managerOnDuty: manager.trim() || undefined,
                tags,
                note: note.trim() || undefined,
                recordedAt: existing?.recordedAt ?? now,
                updatedAt: now,
              })
            }
          >
            SAVE CONTEXT
          </button>
        </div>
      </div>
    </div>
  );
}

type ShiftRatingInput = {
  overallRating: number;
  managerRating: number;
  managerOnDuty?: string;
  tags: ShiftContextTag[];
  note?: string;
};

function ShiftRatingEditor({
  shift,
  mode,
  onSave,
}: {
  shift: Shift;
  mode: "post-clockout" | "history";
  onSave: (review: ShiftRatingInput) => void;
}) {
  const [overallRating, setOverallRating] = useState<ShiftRatingValue>(
    shift.ratingReview?.overallRating ?? 3,
  );
  const [managerRating, setManagerRating] = useState<ShiftRatingValue>(
    shift.ratingReview?.managerRating ?? 3,
  );
  const [managerOnDuty, setManagerOnDuty] = useState(
    shift.context?.managerOnDuty ?? "",
  );
  const [tags, setTags] = useState<ShiftContextTag[]>(
    shift.context?.tags ?? [],
  );
  const [note, setNote] = useState(shift.context?.note ?? "");
  const [saved, setSaved] = useState(false);
  const blockedMs = blockedTimeBreakdown(shift).reduce(
    (total, item) => total + item.durationMs,
    0,
  );
  const outcomes = taskOutcomeSummary(shift);
  const deliveries = deliverySummary(shift).individual;
  const toggleTag = (tag: ShiftContextTag) => {
    setSaved(false);
    setTags((current) =>
      current.includes(tag)
        ? current.filter((item) => item !== tag)
        : [...current, tag],
    );
  };
  const save = () => {
    onSave({
      overallRating,
      managerRating,
      managerOnDuty: managerOnDuty.trim() || undefined,
      tags,
      note: note.trim() || undefined,
    });
    setSaved(true);
  };
  return (
    <section className={`panel shift-rating-editor ${mode}`}>
      <div className="section-title">
        <div>
          <p className="eyebrow">SHIFT REVIEW</p>
          <h2>How did it actually go?</h2>
        </div>
        {shift.ratingReview && <small>EDITABLE</small>}
      </div>
      <p className="settings-help">
        Your candid labels stay private. Professional reports translate them
        into neutral wording.
      </p>
      <div className="shift-review-facts" aria-label="Recorded shift facts">
        <span><small>Blocked time</small><strong>{formatDuration(blockedMs, true)}</strong></span>
        <span><small>Management blocked</small><strong>{outcomes.managementBlocked}</strong></span>
        <span><small>Completed tasks</small><strong>{outcomes.completed}</strong></span>
        <span><small>Deliveries</small><strong>{deliveries}</strong></span>
      </div>
      <label className="rating-control">
        <span><strong>Review the shift</strong><em>{shiftOverallRatingLabel(overallRating)}</em></span>
        <input
          type="range"
          min="1"
          max="5"
          step="1"
          value={overallRating}
          aria-label="Overall shift rating"
          onChange={(event) => {
            setOverallRating(Number(event.target.value) as ShiftRatingValue);
            setSaved(false);
          }}
        />
        <small><span>Shit show</span><span>Excellent</span></small>
      </label>
      <label className="rating-control manager-rating-control">
        <span><strong>Rate the manager</strong><em>{managerRatingLabel(managerRating)}</em></span>
        <input
          type="range"
          min="1"
          max="5"
          step="1"
          value={managerRating}
          aria-label="Manager rating"
          onChange={(event) => {
            setManagerRating(Number(event.target.value) as ShiftRatingValue);
            setSaved(false);
          }}
        />
        <small><span>Idiot in charge</span><span>Excellent</span></small>
      </label>
      <label className="shift-review-manager">
        Manager on duty
        <input
          value={managerOnDuty}
          maxLength={100}
          onChange={(event) => {
            setManagerOnDuty(event.target.value);
            setSaved(false);
          }}
          placeholder="Optional name"
        />
      </label>
      <fieldset className="shift-review-tags" aria-label="What affected this shift?">
        <legend>What affected this shift?</legend>
        {SHIFT_CONTEXT_OPTIONS.map((item) => (
          <button
            type="button"
            key={item.value}
            className={tags.includes(item.value) ? "selected" : ""}
            aria-pressed={tags.includes(item.value)}
            onClick={() => toggleTag(item.value)}
          >
            {shiftContextTagLabel(item.value)}
          </button>
        ))}
      </fieldset>
      <label className="shift-review-note">
        Optional note
        <textarea
          rows={3}
          maxLength={500}
          value={note}
          onChange={(event) => {
            setNote(event.target.value);
            setSaved(false);
          }}
          placeholder="Anything worth remembering about this shift?"
        />
      </label>
      <button type="button" className="confirm-primary shift-review-save" onClick={save}>
        {saved ? "REVIEW SAVED ✓" : shift.ratingReview ? "UPDATE REVIEW" : "SAVE REVIEW"}
      </button>
      {mode === "history" && saved && (
        <small className="shift-review-draft-note">Use Save Shift below to keep this History edit.</small>
      )}
    </section>
  );
}

function ShiftReviewExtras({
  shift,
  history,
  onChange,
}: {
  shift: Shift;
  history: Shift[];
  onChange: (updater: (value: Shift) => void) => void;
}) {
  const anomalies = shiftAnomalies(shift, history);
  return (
    <>
      <ShiftRatingEditor
        key={`history-${shift.id}`}
        shift={shift}
        mode="history"
        onSave={(review) =>
          onChange((value) => {
            applyShiftRatingReview(value, review, new Date().toISOString());
          })
        }
      />
      <section className="panel edit-section incident-review">
        <div className="section-title">
          <div>
            <p className="eyebrow">INCIDENT MARKERS</p>
            <h2>{shift.incidents?.length ?? 0} captured</h2>
          </div>
        </div>
        {(shift.incidents ?? []).length ? (
          (shift.incidents ?? []).map((incident) => (
            <article key={incident.id}>
              <strong>
                {new Date(incident.capturedAt).toLocaleString("en-GB", {
                  dateStyle: "medium",
                  timeStyle: "short",
                })}
              </strong>
              <small>
                {incident.activityId
                  ? "Captured during an active task or delivery"
                  : "Shift-level marker"}
              </small>
              <label>
                Category
                <select
                  value={incident.category ?? ""}
                  onChange={(event) =>
                    onChange((value) => {
                      const item = value.incidents?.find(
                        (entry) => entry.id === incident.id,
                      );
                      if (item) {
                        item.category = event.target.value
                          ? (event.target.value as ShiftIncidentCategory)
                          : undefined;
                        item.updatedAt = new Date().toISOString();
                      }
                    })
                  }
                >
                  <option value="">Choose later</option>
                  {INCIDENT_CATEGORIES.map((item) => (
                    <option value={item.value} key={item.value}>
                      {item.label}
                    </option>
                  ))}
                </select>
              </label>
              <label>
                Manager / context
                <input
                  value={incident.manager ?? ""}
                  onChange={(event) =>
                    onChange((value) => {
                      const item = value.incidents?.find(
                        (entry) => entry.id === incident.id,
                      );
                      if (item) item.manager = event.target.value;
                    })
                  }
                />
              </label>
              <label>
                Note
                <textarea
                  rows={2}
                  maxLength={500}
                  value={incident.note ?? ""}
                  onChange={(event) =>
                    onChange((value) => {
                      const item = value.incidents?.find(
                        (entry) => entry.id === incident.id,
                      );
                      if (item) item.note = event.target.value;
                    })
                  }
                  placeholder="Do not include customer names or addresses"
                />
              </label>
            </article>
          ))
        ) : (
          <p className="muted-copy">
            No incident markers were captured during this shift.
          </p>
        )}
      </section>
      <section className="panel edit-section anomaly-review">
        <div className="section-title">
          <div>
            <p className="eyebrow">REVIEW SUGGESTIONS</p>
            <h2>
              {anomalies.length
                ? `${anomalies.length} to check`
                : "No unusual records found"}
            </h2>
          </div>
        </div>
        <p className="settings-help">
          Suggestions are rule-based prompts, not factual errors, and never
          affect payroll.
        </p>
        {anomalies.map((item) => (
          <article key={item.id}>
            <div>
              <strong>{item.title}</strong>
              <small>{item.explanation}</small>
            </div>
            <label>
              Optional note
              <input
                maxLength={280}
                placeholder="Add context before deciding"
              />
            </label>
            <div className="anomaly-review-actions">
              <button
                type="button"
                onClick={(event) =>
                  onChange((value) => {
                    value.anomalyReviews ??= [];
                    value.anomalyReviews.push({
                      rule: item.rule,
                      status: "dismissed",
                      note:
                        (
                          event.currentTarget
                            .closest("article")
                            ?.querySelector("input") as HTMLInputElement | null
                        )?.value.trim() || undefined,
                      updatedAt: new Date().toISOString(),
                    });
                  })
                }
              >
                NOT AN ISSUE
              </button>
              <button
                type="button"
                className="confirm-primary"
                onClick={(event) =>
                  onChange((value) => {
                    value.anomalyReviews ??= [];
                    value.anomalyReviews.push({
                      rule: item.rule,
                      status: "expected",
                      note:
                        (
                          event.currentTarget
                            .closest("article")
                            ?.querySelector("input") as HTMLInputElement | null
                        )?.value.trim() || undefined,
                      updatedAt: new Date().toISOString(),
                    });
                  })
                }
              >
                THIS WAS EXPECTED
              </button>
            </div>
          </article>
        ))}
      </section>
    </>
  );
}

function TrendsPage({
  data,
  now,
  onBack,
}: {
  data: AppData;
  now: Date;
  onBack: () => void;
}) {
  const [range, setRange] = useState<TrendRange>("4w");
  const summary = buildTrendSummary(data, range, now);
  const metrics = [
    ["Worked hours", summary.workedHours.toFixed(1)],
    ["Gross wages", formatMoney(summary.grossWagesPence)],
    ["Deliveries", String(summary.deliveries)],
    ["Deliveries / hour", summary.deliveriesPerHour.toFixed(2)],
    [
      "Average delivery",
      summary.averageDeliveryMinutes == null
        ? "Not enough data"
        : `${summary.averageDeliveryMinutes.toFixed(1)} min`,
    ],
    [
      "Average customer time",
      summary.averageCustomerMinutes == null
        ? "Not enough data"
        : `${summary.averageCustomerMinutes.toFixed(1)} min`,
    ],
    ["Mileage", `${summary.mileage.toFixed(1)} mi`],
    ["Fuel reimbursement", formatMoney(summary.fuelPence)],
    [
      "Punctuality",
      summary.punctualityPercent == null
        ? "No rota sample"
        : `${summary.punctualityPercent.toFixed(0)}%`,
    ],
    [
      "Attendance",
      summary.attendancePercent == null
        ? "No rota sample"
        : `${summary.attendancePercent.toFixed(0)}%`,
    ],
    [
      "Real trip outside zone",
      summary.realHustleMinutes == null
        ? "No GPS sample"
        : `${summary.realHustleMinutes.toFixed(1)} min avg`,
      "35 m exit → re-entry · outbound + customer + return",
    ],
    [
      "Domino’s trip outside zone",
      summary.dominosHustleMinutes == null
        ? "No GPS sample"
        : `${summary.dominosHustleMinutes.toFixed(1)} min avg`,
      "Saved radius per run · exit → re-entry · outbound + customer + return",
    ],
    ["Store-work time", `${summary.storeWorkHours.toFixed(1)} h`],
  ];
  return (
    <div className="page-stack trends-page">
      <button className="back-button" onClick={onBack}>
        ← Dashboard
      </button>
      <div className="page-heading">
        <p className="eyebrow">LONG-TERM TRENDS</p>
        <h1>Your work over time</h1>
        <p>Beta inclusion follows your existing reporting setting.</p>
      </div>
      <div className="trend-range-tabs">
        {(["4w", "3m", "6m", "overall"] as TrendRange[]).map((item) => (
          <button
            className={range === item ? "active" : ""}
            key={item}
            onClick={() => setRange(item)}
          >
            {item === "4w"
              ? "4 WEEKS"
              : item === "3m"
                ? "3 MONTHS"
                : item === "6m"
                  ? "6 MONTHS"
                  : "OVERALL"}
          </button>
        ))}
      </div>
      {summary.smallSample && (
        <p className="trend-sample-warning">
          Only {summary.sampleSize} completed shift
          {summary.sampleSize === 1 ? "" : "s"} in this period. Treat averages
          cautiously.
        </p>
      )}
      <section className="panel trend-metric-grid">
        {metrics.map(([label, value, detail]) => (
          <span key={label}>
            <small>{label}</small>
            <strong>{value}</strong>
            {detail && <em>{detail}</em>}
          </span>
        ))}
      </section>
    </div>
  );
}

function RecoveryCentrePage({
  data,
  onBack,
  onOpenShift,
  onRestore,
}: {
  data: AppData;
  onBack: () => void;
  onOpenShift: (id: string) => void;
  onRestore: (data: AppData) => Promise<void>;
}) {
  const [inspection, setInspection] = useState<RecoveryCentreInspection | null>(
    null,
  );
  const [health, setHealth] = useState<DataHealthResult | null>(null);
  const [previewId, setPreviewId] = useState<string | null>(null);
  const [restoreId, setRestoreId] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const inspect = async () => {
    setBusy(true);
    setError("");
    try {
      setInspection(await inspectRecoveryCentre());
    } catch (reason) {
      setError(
        reason instanceof Error
          ? reason.message
          : "Recovery data could not be inspected.",
      );
    } finally {
      setBusy(false);
    }
  };
  useEffect(() => {
    const timer = window.setTimeout(() => void inspect(), 0);
    return () => window.clearTimeout(timer);
  }, []);
  const selected =
    inspection?.items.find((item) => item.id === previewId) ?? null;
  const restore =
    inspection?.items.find((item) => item.id === restoreId) ?? null;
  const counts = (value: AppData) => ({
    shifts: value.shifts.length,
    deliveries: value.shifts.reduce(
      (sum, shift) => sum + deliverySummary(shift).individual,
      0,
    ),
    routes: value.shifts
      .flatMap((shift) => shift.activities ?? [])
      .filter((item) => item.routeEvidence?.points.length).length,
  });
  const exportItem = async (value: AppData, label: string) => {
    const backup = createBackupDocument(value, WEB_APP_VERSION);
    await saveExportFile(
      `shift-tracker-recovery-${label}-${new Date().toISOString().replaceAll(":", "-")}.json`,
      JSON.stringify(backup, null, 2),
      "application/json",
    );
  };
  return (
    <div className="page-stack recovery-centre-page">
      <button className="back-button" onClick={onBack}>
        ← Settings
      </button>
      <div className="page-heading">
        <p className="eyebrow">RECOVERY CENTRE</p>
        <h1>Protected tracker copies</h1>
        <p>
          Inspecting and validating are read-only. Restore always requires a
          preview and explicit confirmation.
        </p>
      </div>
      <section className="panel health-check-card">
        <div>
          <p className="eyebrow">DATA HEALTH SELF-CHECK</p>
          <h2>
            {health
              ? health.status === "healthy"
                ? "Tracker data healthy"
                : `${health.issues.length} items need review`
              : "Verify tracker data"}
          </h2>
          <p>
            Checks reconstructed data and record relationships without changing
            anything.
          </p>
        </div>
        <button
          className="confirm-primary"
          onClick={() => setHealth(verifyTrackerData(data))}
        >
          VERIFY TRACKER DATA
        </button>
        {health?.issues.map((item, index) => (
          <button
            className="health-issue-row"
            key={`${item.code}-${index}`}
            onClick={() => item.shiftId && onOpenShift(item.shiftId)}
          >
            <span>
              <strong>{item.message}</strong>
              <small>{item.code.replaceAll("_", " ")}</small>
            </span>
            {item.shiftId && <b>OPEN →</b>}
          </button>
        ))}
      </section>
      <section className="panel recovery-list">
        <div className="section-title">
          <div>
            <p className="eyebrow">LOCAL RECOVERY</p>
            <h2>
              {inspection?.databaseName ?? "ShiftTrackerDB"}{" "}
              {inspection ? `v${inspection.databaseVersion}` : ""}
            </h2>
          </div>
          <button onClick={() => void inspect()} disabled={busy}>
            {busy ? "VALIDATING…" : "VALIDATE"}
          </button>
        </div>
        {error && <p className="form-error">{error}</p>}
        {inspection?.items.map((item) => (
          <article key={item.id} className={item.valid ? "healthy" : "warning"}>
            <div>
              <strong>{item.label}</strong>
              <small>
                {item.savedAt
                  ? new Date(item.savedAt).toLocaleString("en-GB", {
                      dateStyle: "medium",
                      timeStyle: "short",
                    })
                  : item.kind === "legacy"
                    ? "Protected migration source"
                    : "Date unavailable"}
                {item.revision != null ? ` · revision ${item.revision}` : ""}
              </small>
            </div>
            <b>{item.valid ? "HEALTHY" : "WARNING"}</b>
            <div>
              <button
                disabled={!item.data}
                onClick={() => setPreviewId(item.id)}
              >
                PREVIEW
              </button>
              <button
                disabled={!item.data}
                onClick={() =>
                  item.data && void exportItem(item.data, item.kind)
                }
              >
                EXPORT
              </button>
              {item.kind !== "current" && (
                <button
                  disabled={!item.data}
                  onClick={() => setRestoreId(item.id)}
                >
                  RESTORE…
                </button>
              )}
            </div>
          </article>
        ))}
        <article className="hosted-recovery-disabled">
          <div>
            <strong>Hosted backup</strong>
            <small>Not enabled · local IndexedDB remains authoritative</small>
          </div>
          <b>OFF</b>
        </article>
      </section>
      {selected?.data && (
        <div className="modal-backdrop">
          <div
            className="confirm-modal"
            role="dialog"
            aria-modal="true"
            aria-labelledby="recovery-preview-title"
          >
            <p className="eyebrow">RECOVERY PREVIEW</p>
            <h2 id="recovery-preview-title">{selected.label}</h2>
            {(() => {
              const value = counts(selected.data!);
              return (
                <div className="recovery-preview-counts">
                  <span>
                    <small>SHIFTS</small>
                    <strong>{value.shifts}</strong>
                  </span>
                  <span>
                    <small>DELIVERIES</small>
                    <strong>{value.deliveries}</strong>
                  </span>
                  <span>
                    <small>ROUTES</small>
                    <strong>{value.routes}</strong>
                  </span>
                </div>
              );
            })()}
            <p>
              This preview does not expose raw JSON or customer location data.
            </p>
            <div>
              <button
                className="confirm-primary"
                onClick={() => setPreviewId(null)}
              >
                CLOSE
              </button>
            </div>
          </div>
        </div>
      )}
      {restore?.data && (
        <div className="modal-backdrop">
          <div
            className="confirm-modal"
            role="dialog"
            aria-modal="true"
            aria-labelledby="recovery-restore-title"
          >
            <p className="eyebrow">CONFIRM RESTORE</p>
            <h2 id="recovery-restore-title">Replace current tracker data?</h2>
            <p>
              <strong>{restore.label}</strong> has validated. This transaction
              will replace the current logical dataset while preserving recovery
              protection.
            </p>
            <div>
              <button onClick={() => setRestoreId(null)}>CANCEL</button>
              <button
                className="confirm-danger"
                disabled={busy}
                onClick={() => {
                  setBusy(true);
                  void onRestore(restore.data!)
                    .then(() => {
                      setRestoreId(null);
                      return inspect();
                    })
                    .catch((reason) =>
                      setError(
                        reason instanceof Error
                          ? reason.message
                          : "Restore failed.",
                      ),
                    )
                    .finally(() => setBusy(false));
                }}
              >
                RESTORE VALIDATED COPY
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function HostedBackupPanel({
  data,
  onOpenRecovery,
}: {
  data: AppData;
  onOpenRecovery: () => void;
}) {
  const [capability, setCapability] = useState(() => readHostedCapability());
  const [diagnostics, setDiagnostics] = useState(() =>
    hostedBackupDiagnostics(),
  );
  const [shownKey, setShownKey] = useState("");
  const [acknowledged, setAcknowledged] = useState(false);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState("");
  const [connectionUsable, setConnectionUsable] = useState(() =>
    hostedSyncConnectionUsable(),
  );
  useEffect(() => {
    const refresh = () => {
      setCapability(readHostedCapability());
      setDiagnostics(hostedBackupDiagnostics());
    };
    window.addEventListener("shift-tracker-hosted-status", refresh);
    return () =>
      window.removeEventListener("shift-tracker-hosted-status", refresh);
  }, []);
  useEffect(() => {
    const refreshConnection = () => setConnectionUsable(hostedSyncConnectionUsable());
    const connection = (navigator as Navigator & {
      connection?: { addEventListener?: (event: "change", listener: () => void) => void; removeEventListener?: (event: "change", listener: () => void) => void };
    }).connection;
    window.addEventListener("online", refreshConnection);
    window.addEventListener("offline", refreshConnection);
    connection?.addEventListener?.("change", refreshConnection);
    return () => {
      window.removeEventListener("online", refreshConnection);
      window.removeEventListener("offline", refreshConnection);
      connection?.removeEventListener?.("change", refreshConnection);
    };
  }, []);
  const prepare = () => {
    const value = capability ?? setHostedBackupEnabled(false);
    setCapability(value);
    setShownKey(exportRecoveryKey(value));
    setAcknowledged(false);
  };
  const copyKey = async () => {
    const key = shownKey || exportRecoveryKey();
    await navigator.clipboard.writeText(key);
    setShownKey(key);
    setMessage("Recovery key copied");
  };
  const enable = async () => {
    if (!acknowledged) return;
    setHostedBackupEnabled(true);
    setCapability(readHostedCapability());
    setBusy(true);
    setMessage("");
    try {
      await queueHostedCheckpoint(data, "Hosted backup enabled");
      setMessage("Encrypted checkpoint uploaded and verified");
    } catch (error) {
      setMessage(
        error instanceof Error
          ? error.message
          : "Hosted backup could not upload yet. Local saving is unaffected.",
      );
    } finally {
      setBusy(false);
    }
  };
  return (
    <section className="panel hosted-backup-panel">
      <div className="section-title">
        <div>
          <p className="eyebrow">OPTIONAL HOSTED RECOVERY</p>
          <h2>Encrypted cloud checkpoints</h2>
        </div>
        <b>{capability?.backupEnabled ? "ON" : "OFF"}</b>
      </div>
      <p>
        IndexedDB remains authoritative. Only validated, encrypted checkpoints
        follow meaningful local saves; GPS samples never upload individually.
      </p>
      <div className="hosted-sync-status" role="status">
        <span>
          <small>SYNC STATUS</small>
          <b>
            {!capability?.backupEnabled
              ? "Automatic backup off"
              : diagnostics.pendingReason
              ? connectionUsable
                ? "Syncing next saved copy"
                : "Waiting for a better connection"
              : diagnostics.lastSuccessAt
                ? "Backed up"
                : "Waiting for first backup"}
          </b>
        </span>
        <span>
          <small>LAST VERIFIED</small>
          <b>
            {diagnostics.lastSuccessAt
              ? new Date(diagnostics.lastSuccessAt).toLocaleString("en-GB")
              : "Not yet"}
          </b>
        </span>
        <span>
          <small>RETENTION</small>
          <b>One copy per day · 3 days</b>
        </span>
      </div>
      <button className="hosted-recovery-open" onClick={onOpenRecovery}>
        VIEW &amp; RESTORE BACKUPS
      </button>
      {!shownKey && (
        <button className="confirm-primary" onClick={prepare}>
          {capability ? "SHOW RECOVERY KEY" : "SET UP HOSTED BACKUP"}
        </button>
      )}
      {shownKey && (
        <div className="recovery-key-box">
          <label>
            Your user-held recovery key
            <textarea readOnly rows={4} value={shownKey} />
          </label>
          <div>
            <button onClick={() => void copyKey()}>COPY KEY</button>
            <button
              onClick={() =>
                void saveExportFile(
                  "shift-tracker-recovery-key.txt",
                  `${shownKey}\n`,
                  "text/plain",
                )
              }
            >
              SAVE KEY FILE
            </button>
          </div>
          <label className="recovery-key-ack">
            <input
              type="checkbox"
              checked={acknowledged}
              onChange={(event) => setAcknowledged(event.target.checked)}
            />{" "}
            I have saved this key somewhere separate from this device.
          </label>
        </div>
      )}
      {!capability?.backupEnabled ? (
        <button disabled={!acknowledged || busy} onClick={() => void enable()}>
          ENABLE &amp; VERIFY FIRST CHECKPOINT
        </button>
      ) : (
        <>
          <button
            disabled={busy}
            onClick={() => {
              setBusy(true);
              void queueHostedCheckpoint(
                data,
                diagnostics.pendingReason ?? "Manual recovery checkpoint",
              )
                .then(() =>
                  setMessage("Encrypted checkpoint uploaded and verified"),
                )
                .catch((error) =>
                  setMessage(
                    error instanceof Error
                      ? error.message
                      : "Retry failed; local saving is unaffected.",
                  ),
                )
                .finally(() => setBusy(false));
            }}
          >
            {busy
              ? "UPLOADING…"
              : diagnostics.pendingReason
                ? "RETRY HOSTED CHECKPOINT"
                : "CREATE CHECKPOINT NOW"}
          </button>
          <button
            onClick={() => {
              setHostedBackupEnabled(false);
              setCapability(readHostedCapability());
            }}
          >
            TURN OFF AUTOMATIC CHECKPOINTS
          </button>
        </>
      )}
      <small>
        {diagnostics.lastSuccessAt
          ? `Last verified ${new Date(diagnostics.lastSuccessAt).toLocaleString("en-GB")}. `
          : ""}
        {diagnostics.pendingReason
          ? `Pending: ${diagnostics.pendingReason}. `
          : ""}
        {diagnostics.lastError ?? message}
      </small>
    </section>
  );
}

function CloudRecoveryPanel({
  onRestore,
}: {
  onRestore: (data: AppData) => Promise<void>;
}) {
  const [key, setKey] = useState("");
  const [items, setItems] = useState<HostedCheckpoint[]>([]);
  const [preview, setPreview] = useState<{
    checkpoint: HostedCheckpoint;
    data: AppData;
  } | null>(null);
  const [confirming, setConfirming] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const capability = readHostedCapability();
  const load = async () => {
    setBusy(true);
    setError("");
    try {
      setItems(await listHostedCheckpoints());
    } catch (reason) {
      setError(
        reason instanceof Error
          ? reason.message
          : "Cloud Recovery could not be loaded.",
      );
    } finally {
      setBusy(false);
    }
  };
  useEffect(() => {
    const timer = capability ? window.setTimeout(() => void load(), 0) : null;
    return () => {
      if (timer != null) window.clearTimeout(timer);
    };
  }, []);
  return (
    <section className="panel cloud-recovery-panel">
      <div className="section-title">
        <div>
          <p className="eyebrow">CLOUD RECOVERY</p>
          <h2>User-key encrypted checkpoints</h2>
        </div>
        <button disabled={busy || !capability} onClick={() => void load()}>
          {busy ? "LOADING…" : "REFRESH"}
        </button>
      </div>
      {!capability && (
        <div className="recovery-key-import">
          <p>
            Enter the recovery key you stored separately. It is kept on this
            device and never sent to the server.
          </p>
          <textarea
            rows={4}
            value={key}
            onChange={(event) => setKey(event.target.value)}
            placeholder="STRK1.…"
          />
          <button
            onClick={() => {
              try {
                importRecoveryKey(key, false);
                setKey("");
                void load();
              } catch (reason) {
                setError(
                  reason instanceof Error
                    ? reason.message
                    : "Recovery key invalid.",
                );
              }
            }}
          >
            USE RECOVERY KEY
          </button>
        </div>
      )}
      {error && <p className="form-error">{error}</p>}
      {capability && !items.length && !busy && (
        <p>No hosted checkpoints found.</p>
      )}
      {items.map((item) => (
        <article
          key={item.id}
          className={item.status === "verified" ? "healthy" : "warning"}
        >
          <div>
            <strong>{item.reason}</strong>
            <small>
              {new Date(item.created_at).toLocaleString("en-GB")} · Web{" "}
              {item.app_version} · expires{" "}
              {new Date(item.expires_at).toLocaleDateString("en-GB")}
            </small>
          </div>
          <b>{item.status.toUpperCase()}</b>
          <div>
            <button
              disabled={item.status !== "verified" || busy}
              onClick={() => {
                setBusy(true);
                void downloadHostedCheckpoint(item.id)
                  .then((data) => setPreview({ checkpoint: item, data }))
                  .catch((reason) =>
                    setError(
                      reason instanceof Error
                        ? reason.message
                        : "Checkpoint validation failed.",
                    ),
                  )
                  .finally(() => setBusy(false));
              }}
            >
              DOWNLOAD &amp; VALIDATE
            </button>
          </div>
        </article>
      ))}
      {preview && (
        <div className="modal-backdrop">
          <div className="confirm-modal" role="dialog" aria-modal="true">
            <p className="eyebrow">CLOUD RECOVERY PREVIEW</p>
            <h2>{preview.checkpoint.reason}</h2>
            <p>
              {preview.data.shifts.length} shifts ·{" "}
              {preview.data.shifts.reduce(
                (sum, shift) => sum + deliverySummary(shift).individual,
                0,
              )}{" "}
              deliveries. Decryption and canonical validation passed.
            </p>
            <div>
              <button
                onClick={() => {
                  setPreview(null);
                  setConfirming(false);
                }}
              >
                CLOSE
              </button>
              <button
                onClick={() =>
                  void saveExportFile(
                    `shift-tracker-cloud-recovery-${preview.checkpoint.id}.json`,
                    JSON.stringify(
                      createBackupDocument(preview.data, WEB_APP_VERSION),
                      null,
                      2,
                    ),
                    "application/json",
                  )
                }
              >
                EXPORT
              </button>
              <button
                className="confirm-danger"
                onClick={() => setConfirming(true)}
              >
                RESTORE…
              </button>
            </div>
            {confirming && (
              <div className="cloud-restore-confirm">
                <p>
                  This replaces the current local dataset transactionally.
                  Existing recovery protection remains.
                </p>
                <button
                  className="confirm-danger"
                  disabled={busy}
                  onClick={() => {
                    setBusy(true);
                    void onRestore(preview.data)
                      .then(() => {
                        setPreview(null);
                        setConfirming(false);
                      })
                      .catch((reason) =>
                        setError(
                          reason instanceof Error
                            ? reason.message
                            : "Restore failed.",
                        ),
                      )
                      .finally(() => setBusy(false));
                  }}
                >
                  CONFIRM VALIDATED RESTORE
                </button>
              </div>
            )}
          </div>
        </div>
      )}
    </section>
  );
}

function SharedReportsManager() {
  const [items, setItems] = useState<SharedReportRecord[]>([]);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const [renderedAt] = useState(() => Date.now());
  const load = async () => {
    if (!readHostedCapability()) return setItems([]);
    setBusy(true);
    setError("");
    try {
      setItems(await listSharedReports());
    } catch (reason) {
      setError(
        reason instanceof Error
          ? reason.message
          : "Shared reports could not be loaded.",
      );
    } finally {
      setBusy(false);
    }
  };
  useEffect(() => {
    const timer = window.setTimeout(() => void load(), 0);
    return () => window.clearTimeout(timer);
  }, []);
  return (
    <section className="panel shared-reports-manager">
      <div className="section-title">
        <div>
          <p className="eyebrow">SHARED REPORTS</p>
          <h2>Frozen report links</h2>
        </div>
        <button disabled={busy} onClick={() => void load()}>
          {busy ? "LOADING…" : "REFRESH"}
        </button>
      </div>
      {error && <p className="form-error">{error}</p>}
      {!items.length && <p>No shared reports yet.</p>}
      {items.map((item) => {
        const expired = Date.parse(item.expires_at) <= renderedAt;
        const state =
          item.status === "revoked"
            ? "REVOKED"
            : expired
              ? "EXPIRED"
              : "ACTIVE";
        return (
          <article key={item.id}>
            <div>
              <strong>{item.title}</strong>
              <small>
                {state} · {item.route_privacy} route · expires{" "}
                {new Date(item.expires_at).toLocaleString("en-GB")}
              </small>
            </div>
            <div>
              <button
                disabled={state !== "ACTIVE"}
                onClick={() => void navigator.clipboard.writeText(item.url)}
              >
                COPY LINK
              </button>
              <a href={item.url} target="_blank" rel="noreferrer">
                OPEN
              </a>
              <button
                disabled={state !== "ACTIVE"}
                onClick={() => {
                  void revokeSharedReport(item)
                    .then(load)
                    .catch((reason) =>
                      setError(
                        reason instanceof Error
                          ? reason.message
                          : "Revoke failed.",
                      ),
                    );
                }}
              >
                REVOKE NOW
              </button>
            </div>
          </article>
        );
      })}
    </section>
  );
}

function ShareReportModal({
  data,
  request,
  onClose,
}: {
  data: AppData;
  request: { type: "shift" | "week"; shifts: Shift[] };
  onClose: () => void;
}) {
  const [privacy, setPrivacy] = useState<RoutePrivacy>("simplified");
  const [result, setResult] = useState<{
    url: string;
    expiresAt: string;
    id: string;
    revokeToken: string;
  } | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const generate = async () => {
    if (!request.shifts.length)
      return setError("There are no included shifts in this week to share.");
    setBusy(true);
    setError("");
    try {
      const report = buildFrozenSharedReport(data, request.shifts, privacy);
      setResult(await createSharedReport(report));
    } catch (reason) {
      setError(
        reason instanceof Error
          ? reason.message
          : "The shared report could not be created.",
      );
    } finally {
      setBusy(false);
    }
  };
  return (
    <div className="modal-backdrop">
      <div
        className="confirm-modal share-report-modal"
        role="dialog"
        aria-modal="true"
      >
        <p className="eyebrow">SHARE {request.type.toUpperCase()} REPORT</p>
        <h2>Frozen, read-only link</h2>
        <p>
          This creates a privacy-sanitised snapshot, not access to your live
          tracker. It expires after 7 days.
        </p>
        {!result ? (
          <>
            <label>
              Route privacy
              <select
                value={privacy}
                onChange={(event) =>
                  setPrivacy(event.target.value as RoutePrivacy)
                }
              >
                <option value="simplified">
                  Simplified evidence route (recommended)
                </option>
                <option value="none">No route map</option>
                <option value="full">Full retained evidence route</option>
              </select>
            </label>
            <p className="settings-help">
              Customer names, typed addresses, house numbers, API keys, private
              settings and unrelated shifts are excluded.
            </p>
            {error && <p className="form-error">{error}</p>}
            <div>
              <button onClick={onClose}>CANCEL</button>
              <button
                className="confirm-primary"
                disabled={busy}
                onClick={() => void generate()}
              >
                {busy ? "CREATING…" : "CREATE 7-DAY LINK"}
              </button>
            </div>
          </>
        ) : (
          <>
            <label>
              Share link
              <textarea readOnly rows={3} value={result.url} />
            </label>
            <small>
              Expires {new Date(result.expiresAt).toLocaleString("en-GB")}
            </small>
            <div>
              <button
                onClick={() => void navigator.clipboard.writeText(result.url)}
              >
                COPY LINK
              </button>
              <button
                onClick={() => {
                  if (
                    !shareFileWithNativeShell(
                      `shift-tracker-${request.type}-report.txt`,
                      result.url,
                      "text/plain",
                    )
                  )
                    void navigator.share?.({
                      title: "Shift Tracker report",
                      text: result.url,
                      url: result.url,
                    });
                }}
              >
                SHARE…
              </button>
              <a
                className="confirm-primary"
                href={result.url}
                target="_blank"
                rel="noreferrer"
              >
                OPEN
              </a>
              <button
                className="confirm-danger"
                onClick={() => {
                  void revokeSharedReport({
                    id: result.id,
                    revokeToken: result.revokeToken,
                  })
                    .then(onClose)
                    .catch((reason) =>
                      setError(
                        reason instanceof Error
                          ? reason.message
                          : "Revoke failed.",
                      ),
                    );
                }}
              >
                REVOKE NOW
              </button>
            </div>
            {error && <p className="form-error">{error}</p>}
          </>
        )}
      </div>
    </div>
  );
}

function NativeUpdateStatusCards({
  installedAndroidVersion,
  installedWearVersion,
  wearConnected,
}: {
  installedAndroidVersion: string | null;
  installedWearVersion: string | null;
  wearConnected: boolean | null;
}) {
  const [status, setStatus] = useState<NativeApkUpdateMessage | null>(null);
  const [wearStatus, setWearStatus] = useState<NativeWearUpdateMessage | null>(
    null,
  );
  const [updateModal, setUpdateModal] = useState<"android" | "wear" | null>(
    null,
  );
  const [checkModal, setCheckModal] = useState<"android" | "wear" | null>(null);
  useEffect(() => {
    const stop = subscribeToNativeMessages((event) => {
      const android = readNativeApkUpdateMessage(event);
      if (android) setStatus((current) => ({ ...(current ?? {}), ...android }));
      const wear = readNativeWearUpdateMessage(event);
      if (wear) setWearStatus((current) => ({ ...(current ?? {}), ...wear }));
    });
    requestNativeApkUpdate("check", false);
    requestNativeWearUpdate("check", false);
    return stop;
  }, []);
  const state = status?.state;
  const note =
    state === "available"
      ? "UPDATE AVAILABLE"
      : state === "up_to_date" || state === "rate_limited"
        ? "UP TO DATE"
        : state === "web_refresh_required"
          ? "REFRESH WEB APP FIRST"
          : state === "checking"
            ? "CHECKING…"
            : state === "downloading"
              ? "DOWNLOADING & VERIFYING…"
              : state === "installer_opened"
                ? "ANDROID INSTALLER OPENED"
                : state === "unavailable" || state === "failed"
                  ? "CONNECTION UNAVAILABLE"
                  : "CHECK ANDROID APK";
  const latestVersion =
    status?.latestVersion ??
    (state === "up_to_date" || state === "rate_limited"
      ? installedAndroidVersion
      : null);
  const wear = presentWearUpdate(
    wearStatus,
    wearStatus?.installedVersion ?? installedWearVersion,
    wearConnected,
  );
  const startAndroidUpdate = () => {
    setCheckModal(null);
    setUpdateModal("android");
    if (!requestNativeApkUpdate("install"))
      setStatus({
        state: "failed",
        message:
          "The Android app could not start this update. Your installed app is unchanged.",
      });
  };
  const startWearUpdate = () => {
    setCheckModal(null);
    setUpdateModal("wear");
    if (!requestNativeWearUpdate("send"))
      setWearStatus({
        state: "failed",
        message:
          "The Android app could not start the watch update. Your installed apps are unchanged.",
      });
  };
  const checkAndroidUpdate = () => {
    setCheckModal("android");
    setStatus((current) => ({ ...(current ?? {}), state: "checking" }));
    if (!requestNativeApkUpdate("check"))
      setStatus({
        state: "failed",
        message:
          "The Android app could not check for updates. Your installed app is unchanged.",
      });
  };
  const checkWearUpdate = () => {
    setCheckModal("wear");
    setWearStatus((current) => ({ ...(current ?? {}), state: "checking" }));
    if (!requestNativeWearUpdate("check"))
      setWearStatus({
        state: "failed",
        message:
          "The Android app could not check Wear OS updates. Your installed apps are unchanged.",
      });
  };
  return (
    <>
      <details className="app-update-details">
        <summary>
          <span>
            <small>ANDROID APP UPDATES</small>
            <strong>{note}</strong>
          </span>
          <b>{latestVersion ?? installedAndroidVersion ?? "…"}</b>
          <i aria-hidden="true">⌄</i>
        </summary>
        <div className="app-update-details-body">
          <section
            className={`android-update-status${state === "available" ? " update" : ""} compact`}
            aria-label="Android app updates"
          >
            <div className="android-update-versions">
              <span>
                <small>INSTALLED</small>
                <strong>{installedAndroidVersion ?? "Not reported"}</strong>
              </span>
              <span>
                <small>LATEST STABLE</small>
                <strong>{latestVersion ?? "Check GitHub"}</strong>
              </span>
            </div>
            {status?.message && (
              <p className="android-update-message">{status.message}</p>
            )}
            {status?.releaseNotes?.length ? (
              <ul>
                {status.releaseNotes.map((item) => (
                  <li key={item}>{item}</li>
                ))}
              </ul>
            ) : null}
            {state === "available" ? (
              <button
                type="button"
                className="confirm-primary android-update-action"
                onClick={startAndroidUpdate}
              >
                DOWNLOAD APK UPDATE
              </button>
            ) : state === "web_refresh_required" ? (
              <p className="android-update-message">
                Android {status?.latestVersion} needs Web App{" "}
                {status?.minimumWebVersion}+ first. Refresh the Web App, then
                check again.
              </p>
            ) : null}
            <button
              type="button"
              className="android-update-check"
              onClick={checkAndroidUpdate}
            >
              {state === "checking" ? "CHECKING GITHUB…" : "CHECK FOR UPDATES"}
            </button>
            <small className="android-update-help">
              Android updates are separate from web refreshes and are verified
              before Android opens its normal installation screen.
            </small>
          </section>
        </div>
      </details>
      <details className="app-update-details">
        <summary>
          <span>
            <small>WEAR OS UPDATES</small>
            <strong>{wear.label}</strong>
          </span>
          <b>{wear.latestVersion ?? installedWearVersion ?? "…"}</b>
          <i aria-hidden="true">⌄</i>
        </summary>
        <div className="app-update-details-body">
          <section
            className={`android-update-status compact wear-update-status${wearStatus?.state === "available" ? " update" : ""}`}
            aria-label="Wear OS updates"
          >
            <div className="android-update-versions">
              <span>
                <small>INSTALLED</small>
                <strong>
                  {wearStatus?.installedVersion ??
                    installedWearVersion ??
                    "Unavailable"}
                </strong>
              </span>
              <span>
                <small>LATEST STABLE</small>
                <strong>{wear.latestVersion ?? "Check GitHub"}</strong>
              </span>
            </div>
            <p className="android-update-message">
              {wearConnected === true
                ? "Watch connected"
                : wearConnected === false
                  ? "Watch not connected"
                  : "Checking watch connection"}
            </p>
            {wearStatus?.message && (
              <p className="android-update-message">{wearStatus.message}</p>
            )}
            {wear.canSend && (
              <button
                type="button"
                className="confirm-primary android-update-action"
                onClick={startWearUpdate}
              >
                SEND UPDATE TO WATCH
              </button>
            )}
            <button
              type="button"
              className="android-update-check"
              onClick={checkWearUpdate}
              disabled={wear.isBusy}
            >
              {wear.isBusy ? "CHECKING WEAR OS…" : "CHECK FOR UPDATES"}
            </button>
            <small className="android-update-help">
              Wear updates are downloaded, verified and sent by the Android app.
              Confirm installation on the watch.
            </small>
          </section>
        </div>
      </details>
      {updateModal && (
        <NativeUpdateProgressModal
          kind={updateModal}
          status={updateModal === "android" ? status : wearStatus}
          onClose={() => setUpdateModal(null)}
        />
      )}
      {checkModal && (
        <NativeUpdateCheckModal
          kind={checkModal}
          status={checkModal === "android" ? status : wearStatus}
          onClose={() => setCheckModal(null)}
          onUpdate={
            checkModal === "android" ? startAndroidUpdate : startWearUpdate
          }
        />
      )}
    </>
  );
}

function NativeUpdateCheckModal({
  kind,
  status,
  onClose,
  onUpdate,
}: {
  kind: "android" | "wear";
  status: NativeApkUpdateMessage | NativeWearUpdateMessage | null;
  onClose: () => void;
  onUpdate: () => void;
}) {
  const state = status?.state ?? "checking";
  const isChecking = state === "checking";
  const isCurrent = state === "up_to_date" || state === "rate_limited";
  const isAvailable = state === "available";
  const version = status?.latestVersion ?? status?.installedVersion;
  const label = kind === "android" ? "ANDROID" : "WEAR OS";
  const title = isChecking
    ? `Checking ${label} updates`
    : isCurrent
      ? `${label} Update Not Needed`
      : isAvailable
        ? `${label} Update Available`
        : state === "watch_not_connected"
          ? "Watch Not Connected"
          : `${label} Update Check Failed`;
  const message = isCurrent
    ? `${label === "ANDROID" ? "Shift Tracker Android" : "Shift Tracker Wear OS"} ${version ?? ""} is already installed and verified.`
    : isAvailable
      ? `Version ${version ?? ""} is ready to install safely.`
      : state === "watch_not_connected"
        ? "Connect your watch, then try checking again."
        : (status?.message ?? "Your installed app is unchanged.");
  return (
    <div className="modal-backdrop" role="presentation">
      <div
        className={`confirm-modal web-update-modal${isCurrent ? " installed" : isAvailable ? " available" : ""}`}
        role="dialog"
        aria-modal="true"
        aria-labelledby="native-check-title"
      >
        <p className="eyebrow">SHIFT TRACKER {label} UPDATE</p>
        <h2 id="native-check-title">{title}</h2>
        {isChecking ? (
          <div className="web-update-progress" role="status">
            <div className="web-update-progress-ring indeterminate">
              <b>…</b>
            </div>
            <div>
              <strong>Checking GitHub release</strong>
              <p>Looking for a verified Shift Tracker {label} update…</p>
              <div
                className="web-update-progress-track checking"
                aria-hidden="true"
              >
                <i />
              </div>
              <small>Your installed apps and shift data are unchanged.</small>
            </div>
          </div>
        ) : (
          <>
            <div
              className={
                isCurrent
                  ? "web-update-installed-hero"
                  : isAvailable
                    ? "web-update-available"
                    : "web-update-available"
              }
              role="status"
            >
              <div
                className={
                  isCurrent
                    ? "web-update-installed-mark"
                    : "web-update-available-mark"
                }
                aria-hidden="true"
              >
                {isCurrent ? "✓" : isAvailable ? "↓" : "!"}
              </div>
              <div>
                <strong>{version ? `${label} ${version}` : label}</strong>
                <small>
                  {isCurrent
                    ? "Already installed"
                    : isAvailable
                      ? "Ready to install"
                      : "No update was installed"}
                </small>
              </div>
            </div>
            <p>{message}</p>
            <div>
              <button onClick={onClose}>
                {isAvailable ? "LATER" : "DONE"}
              </button>
              {isAvailable && (
                <button className="confirm-primary" onClick={onUpdate}>
                  {kind === "android" ? "DOWNLOAD UPDATE" : "SEND TO WATCH"}
                </button>
              )}
            </div>
          </>
        )}
      </div>
    </div>
  );
}

function NativeUpdateProgressModal({
  kind,
  status,
  onClose,
}: {
  kind: "android" | "wear";
  status: NativeApkUpdateMessage | NativeWearUpdateMessage | null;
  onClose: () => void;
}) {
  const state = status?.state ?? "downloading";
  const version = status?.latestVersion;
  const transferPercent =
    kind === "wear" &&
    status &&
    "transferBytes" in status &&
    "transferTotalBytes" in status &&
    status.transferTotalBytes
      ? Math.min(
          100,
          Math.round(
            ((status.transferBytes ?? 0) / status.transferTotalBytes) * 100,
          ),
        )
      : null;
  const stage =
    kind === "android"
      ? state === "verified"
        ? [
            "Verifying Android update",
            "The APK passed its download check. Checking its signed app identity…",
          ]
        : state === "installer_opened"
          ? [
              "Android installer opened",
              "Android now owns the final install confirmation.",
            ]
          : state === "failed"
            ? [
                "Android update could not finish",
                status?.message ?? "Your installed app is unchanged.",
              ]
            : state === "install_permission_required"
              ? [
                  "Allow Android installs",
                  status?.message ??
                    "Allow Shift Tracker in Android settings, then try again.",
                ]
              : [
                  "Downloading Android update",
                  "Downloading the signed APK securely, then verifying it before Android opens the installer.",
                ]
      : state === "verified"
        ? [
            "Wear update verified",
            "The Wear APK passed verification. Preparing the secure transfer…",
          ]
        : state === "sending_to_watch"
          ? [
              "Sending update to watch",
              "Securely transferring the verified Wear update to your connected watch…",
            ]
          : state === "sent_to_watch"
            ? [
                "Waiting for watch confirmation",
                "The transfer finished. Waiting for the watch to verify its copy before showing installation as ready…",
              ]
            : state === "receiving"
              ? [
                  "Watch receiving update",
                  status?.message ??
                    "The watch is receiving the verified update.",
                ]
              : state === "ready_to_install"
                ? [
                    "Ready to install on watch",
                    status?.message ?? "Confirm installation on the watch.",
                  ]
                : state === "failed"
                  ? [
                      "Wear update could not finish",
                      status?.message ?? "Your installed apps are unchanged.",
                    ]
                  : [
                      "Downloading Wear update",
                      "Downloading the signed Wear APK securely, then verifying and sending it to your watch.",
                    ];
  const complete =
    state === "installer_opened" ||
    state === "ready_to_install" ||
    state === "sent_to_watch" ||
    state === "failed" ||
    state === "install_permission_required";
  return (
    <div className="modal-backdrop" role="presentation">
      <div
        className={`confirm-modal web-update-modal native-update-modal${complete && state !== "failed" ? " installed" : ""}`}
        role="dialog"
        aria-modal="true"
        aria-labelledby="native-update-title"
      >
        <p className="eyebrow">
          SHIFT TRACKER {kind === "android" ? "ANDROID" : "WEAR OS"} UPDATE
        </p>
        <h2 id="native-update-title">{stage[0]}</h2>
        {complete ? (
          <>
            <div
              className={
                state === "failed"
                  ? "web-update-available"
                  : "web-update-installed-hero"
              }
              role="status"
            >
              <div
                className={
                  state === "failed"
                    ? "web-update-available-mark"
                    : "web-update-installed-mark"
                }
                aria-hidden="true"
              >
                {state === "failed" ? "!" : "✓"}
              </div>
              <div>
                <strong>
                  {version
                    ? `${kind === "android" ? "ANDROID" : "WEAR OS"} ${version}`
                    : kind === "android"
                      ? "ANDROID UPDATE"
                      : "WEAR OS UPDATE"}
                </strong>
                <small>
                  {state === "sent_to_watch"
                    ? "Sent securely to your watch"
                    : state === "installer_opened"
                      ? "Ready for Android confirmation"
                      : state === "failed"
                        ? "No update was installed"
                        : "Next step is on your device"}
                </small>
              </div>
            </div>
            <p>
              {state === "sent_to_watch"
                ? "The update was sent successfully. Check the Shift Tracker notification on your watch, then tap it to install."
                : stage[1]}
            </p>
            <div>
              <button className="confirm-primary" onClick={onClose}>
                DONE
              </button>
            </div>
          </>
        ) : (
          <div className="web-update-progress" role="status">
            <div
              className={`web-update-progress-ring${transferPercent === null ? " indeterminate" : ""}`}
              style={
                transferPercent === null
                  ? undefined
                  : ({
                      "--web-update-progress": `${transferPercent}%`,
                    } as CSSProperties)
              }
            >
              <b>{transferPercent === null ? "…" : `${transferPercent}%`}</b>
            </div>
            <div>
              <strong>{stage[0]}</strong>
              <p>{stage[1]}</p>
              <div
                className={`web-update-progress-track${transferPercent === null ? " checking" : ""}`}
                aria-hidden="true"
              >
                <i
                  style={
                    transferPercent === null
                      ? undefined
                      : { width: `${transferPercent}%` }
                  }
                />
              </div>
              <small>
                {transferPercent === null
                  ? kind === "android"
                    ? "Your shift data, GPS evidence and Web App stay untouched."
                    : "Preparing secure transfer…"
                  : `${transferPercent}% sent to watch`}
              </small>
              <button onClick={onClose}>CONTINUE IN BACKGROUND</button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
function EmptyState({ title, text }: { title: string; text: string }) {
  return (
    <div className="empty-state">
      <div>◌</div>
      <strong>{title}</strong>
      <p>{text}</p>
    </div>
  );
}
